class Solution {long long cross(vector<int> a,vector<int> b,vector<int> c){return (1LL*b[0]-a[0])*(1LL*c[1]-a[1])-(1LL*b[1]-a[1])*(1LL*c[0]-a[0]);}bool on(vector<int> p,vector<int> a,vector<int> b){return p[0]>=min(a[0],b[0])&&p[0]<=max(a[0],b[0])&&p[1]>=min(a[1],b[1])&&p[1]<=max(a[1],b[1]);}public:bool solve(vector<vector<int>> first,vector<vector<int>> second){auto a=first[0],b=first[1],c=second[0],d=second[1];long long p=cross(a,b,c),q=cross(a,b,d),r=cross(c,d,a),s=cross(c,d,b);if(p==0&&on(c,a,b)||q==0&&on(d,a,b)||r==0&&on(a,c,d)||s==0&&on(b,c,d))return true;return (p<0&&q>0||p>0&&q<0)&&(r<0&&s>0||r>0&&s<0);}};